/* town/town-egg-fx.js */
'use strict';
(() => {
 const jobs=new Set(),nodes=new Set();
 const game=()=>window.FoamTownGame?.active;
 const quiet=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||game()?.config.muted?.();
 const after=(fn,ms)=>{const id=setTimeout(()=>{jobs.delete(id);fn();},ms);jobs.add(id);return id;};
 function node(html,cls=''){const g=game();if(!g)return null;const n=document.createElement('div');n.className='egg-world-fx '+cls;n.innerHTML=html;n.setAttribute('aria-hidden','true');g.world.append(n);nodes.add(n);return n;}
 function remove(n){n?.remove();nodes.delete(n);}
 function toast(text){const n=document.createElement('div');n.className='egg-toast';n.setAttribute('role','status');n.textContent=text;(document.querySelector('dialog[open]')||document.body).append(n);nodes.add(n);after(()=>remove(n),4200);}
 function bubble(text){const g=game(),n=node('','egg-bubble');if(!n){toast(text);return;}n.textContent=text;n.style.left=g.me.x+'px';n.style.top=(g.me.y-115)+'px';after(()=>remove(n),10000);}
 function pose(id){if(!quiet())window.foamPandaMotion?.play(game()?.avatar(),id);}
 function svg(content,cls='',duration=20000){const g=game();if(!g)return;cls&&g.world.querySelectorAll('.egg-world-fx.'+cls).forEach(remove);const n=node(`<svg viewBox="0 0 ${g.width} ${g.height}" width="${g.width}" height="${g.height}">${content}</svg>`,cls);if(duration)after(()=>remove(n),duration);return n;}
 function grid(){const g=game();if(!g)return;let d='';for(let x=0;x<g.width;x+=48)d+=`M${x} 0V${g.height}`;for(let y=0;y<g.height;y+=48)d+=`M0 ${y}H${g.width}`;svg(`<g fill="none"><path d="${d}" stroke="#8ff7b6" stroke-width="11" opacity=".1"/><path d="${d}" stroke="#b9ffd1" stroke-width="5" opacity=".27"/><path d="${d}" stroke="#f1ffd7" stroke-width="1.4" opacity=".95"/></g>`,'egg-grid');}
 function stream(){const g=game();if(!g)return;svg(g.positions.filter(p=>!p.hidden).map(p=>[-1,1].map(s=>`<path d="M${p.x-55} ${p.y+100+s*25}Q${p.x+100} ${p.y+100+s*185} ${p.x+255} ${p.y+100+s*25}"/>`).join('')).join(''),'egg-stream');}
 function particles(kind='leaf'){const g=game();if(!g)return;const colors=kind==='snow'?['#fff','#e5f9ff']:kind==='paper'?['#fff5cf','#e7dfbe']:['#bedc7b','#efd089','#88bb77'];const n=node('','egg-particles');for(let i=0;i<(quiet()?8:22);i++){const p=document.createElement('i');p.style.cssText=`left:${g.me.x+(Math.random()-.5)*440}px;top:${g.me.y-230+Math.random()*100}px;--egg-color:${colors[i%colors.length]};--egg-dx:${(Math.random()-.5)*110}px;animation-delay:${Math.random()*1.3}s`;if(kind==='snow')p.style.borderRadius='50%';n.append(p);}if(quiet())n.classList.add('is-still');after(()=>remove(n),5000);}
 function water(){const g=game();if(g)svg(`<path d="M0 0H${g.width/2}V${g.height}H0Z" fill="#55bfe3" opacity=".3"/><path d="M${g.width/2} 0V${g.height}" stroke="#e2fbff" stroke-width="8" stroke-dasharray="16 18"/>`,'egg-water');}
 function rainbow(){const g=game();if(!g||g.world.querySelector('.egg-rainbow'))return;const p=g.positions[g.config.buildings.findIndex(b=>b[0]==='spot')];if(!p)return;const n=svg(['#d6857c','#e6b766','#b8d480','#72b9c3','#8d8ebc'].map((c,i)=>`<path d="M${p.x-15} ${p.y+60}Q${p.x+100} ${p.y-160+i*13} ${p.x+215} ${p.y+60}" fill="none" stroke="${c}" stroke-width="7" opacity=".8"/>`).join(''),'egg-rainbow',20000);}
 function note(at,read){const g=game();if(!g)return;g.world.querySelectorAll('.egg-mystery-note').forEach(remove);const n=document.createElement('button');n.type='button';n.className='egg-world-fx egg-mystery-note';n.setAttribute('aria-label','展开神秘小纸条');n.innerHTML='<svg viewBox="0 0 64 50" aria-hidden="true"><path d="M5 6 48 2 59 13 55 45 9 48Z" fill="#fff2c8" stroke="#927648" stroke-width="2"/><path d="m48 2-1 14 12-3M18 22l25-2M19 29l22-2M20 36l14-1" fill="none" stroke="#b89960" stroke-width="2"/></svg><span>神秘纸条</span>';n.style.left=(at.x+105)+'px';n.style.top=(at.y+65)+'px';n.onclick=e=>{e.stopPropagation();read();};g.world.append(n);nodes.add(n);if(!quiet())n.animate([{transform:'translateY(-40px) rotate(-12deg)',opacity:0},{transform:'translateY(12px) rotate(8deg)',opacity:1,offset:.8},{transform:'translateY(0) rotate(-4deg)',opacity:1}],{duration:850,easing:'ease-out',fill:'both'});}
 function appearance(cls,ms=5000){const el=game()?.avatar();if(!el)return;el.classList.add(cls);after(()=>el.classList.remove(cls),quiet()?1000:ms);}
 function retro(){const w=game()?.world;if(!w)return;w.classList.add('egg-retro');after(()=>w.classList.remove('egg-retro'),quiet()?2500:60000);}
 function ghost(){const g=game(),me=g?.avatar();if(!me)return;const n=me.cloneNode(true);n.removeAttribute('data-town');n.removeAttribute('data-user');n.removeAttribute('id');n.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));n.setAttribute('aria-hidden','true');n.tabIndex=-1;n.classList.remove('is-me');n.classList.add('egg-ghost');g.world.append(n);nodes.add(n);const start=performance.now();let previous={...g.me};const tick=()=>{if(game()!==g||performance.now()-start>10000){remove(n);return;}n.style.transform=`translate3d(${previous.x-32}px,${previous.y-62}px,0)`;previous={...g.me};after(tick,300);};tick();}
 let pieces=[];
 function rejoin(){for(const n of pieces){n.style.translate='0 0';after(()=>remove(n),500);}pieces=[];}
 function split(){rejoin();const g=game(),el=g?.avatar();if(!el)return;for(let i=0;i<4;i++){const n=el.cloneNode(true);n.removeAttribute('data-town');n.removeAttribute('data-user');n.setAttribute('aria-hidden','true');n.tabIndex=-1;n.classList.add('egg-ghost','egg-piece');n.style.clipPath=`inset(${i>1?50:0}% ${i%2?0:50}% ${i>1?0:50}% ${i%2?50:0}%)`;g.world.append(n);nodes.add(n);pieces.push(n);if(!quiet())requestAnimationFrame(()=>n.style.translate=`${i%2?27:-27}px ${i>1?27:-27}px`);}after(rejoin,60000);}
 function nap(){const g=game();if(!g)return;pose('sleep');const n=node('<svg viewBox="0 0 60 40"><path d="M30 9Q15 0 3 6v27q15-5 27 3 13-8 27-3V6Q44 0 30 9Z" fill="#f9efcc" stroke="#547953" stroke-width="3"/><path d="M30 9v27M9 13l14 2m-14 6 14 2m14-8 14-2m-14 10 14-2" fill="none" stroke="#b3a978" stroke-width="2"/></svg>','egg-nap-book');n.style.left=g.me.x+'px';n.style.top=(g.me.y-28)+'px';after(()=>remove(n),6000);}
 function clear(){for(const id of jobs)clearTimeout(id);jobs.clear();for(const n of nodes)n.remove();nodes.clear();pieces=[];document.querySelectorAll('.egg-retro,.egg-paper-panda').forEach(n=>n.classList.remove('egg-retro','egg-paper-panda'));}
 // A persistent rainbow stays in the scene when switching browser tabs.
 document.addEventListener('visibilitychange',()=>{if(document.hidden)for(const n of nodes)if(!n.dataset.eggPersistent&&!n.classList.contains('egg-mystery-note'))remove(n);});
 window.FoamTownEggFX={after,toast,bubble,pose,grid,stream,particles,water,rainbow,note,appearance,retro,ghost,split,rejoin,nap,clear,quiet};
})();

