 function npcDetail(m,kind,ms){const original=m.el.querySelector('.town-pixel-panda');if(!original)return null;const before=original.style.backgroundImage;original.style.backgroundImage=`url(/assets/town/npc/${m.npc.id}-without-${kind}.webp),url(/assets/town/panda-walk-v2.webp)`;const detail=original.cloneNode(false);detail.style.backgroundImage=`url(/assets/town/npc/${m.npc.id}-${kind}.webp)`;detail.classList.add('egg-detached-detail');original.parentElement.append(detail);F().after(()=>{detail.remove();original.style.backgroundImage=before;},ms);return detail;}
