  if(kites===5){kites=0;void unlock('C09',kiteCloud);}
  if(a==='jump'&&g.config.province==='sichuan'&&nearBuilding('spot')){if(++jumps===15){jumps=0;const el=g.world.querySelector(`[data-building="${spot().index}"]`);if(!quiet())el?.animate([{rotate:'0deg'},{rotate:'-15deg',offset:.6},{rotate:'12deg',offset:.8},{rotate:'0deg'}],{duration:3500});void unlock('P05');}}
  if(a==='water'&&nearestNPC()?.id==='gardener'){const p={...g.me},n=node(svg('<path d="M100 25q40 60 18 105-20 20-40 0-23-48 22-105Z" fill="#bdd18b" stroke="#67854a" stroke-width="4"/><path d="M77 82l48 11m-52 16 52 10" stroke="#809e56" stroke-width="5"/>'),'egg-garden-shoot',p.x-35,p.y-65,60000);n.role='button';n.tabIndex=0;n.ariaLabel='拾取阿竹赠送的竹笋';n.onclick=async()=>{const r=await event('gardener_pickup');if(r)n.remove();};n.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')n.click();};}
